export function recommendFactorTrack(score){return score<=1?'explorer':score===2?'strategist':'architect'}
export function factorPairs(n){if(!Number.isInteger(n)||n<1)throw new Error('Invalid number');const pairs=[];for(let a=1;a*a<=n;a++)if(n%a===0)pairs.push([a,n/a]);return pairs}
export function factors(n){return[...new Set(factorPairs(n).flat())].sort((a,b)=>a-b)}
export function isPrime(n){return Number.isInteger(n)&&n>1&&factorPairs(n).length===1}
